pragma solidity 0.8.31;

contract ResumeValidator {
    // Storage is the data that is stored on the chain itself
    // persists across transactions
    //
    struct Proof {
        bytes32 hash;
        string CID;
        address owner;
        uint256 timestamp;
    }

    struct Resume {
        bytes32 resumeId;
        bytes32 resumeHash;
        address owner;
        uint256 createdAt;
        bytes32[] proofs;
    }

    mapping(bytes32 => Proof) public proofs;
    mapping(bytes32 => Resume) public resumes;
    // this external here means that we can call this function from outside the blo
    // contract as well as with an RPC or from other places
    function addProof(bytes32 proofHash, string calldata cid) external {
        require(proofs[proofHash].timestamp == 0, "Proof already exist");
        proofs[proofHash] = Proof({
            hash: proofHash,
            CID: cid,
            owner: msg.sender,
            timestamp: block.timestamp
        });
    }

    // public functions here are callable both internally and externally
    function getProof(
        bytes32 proofHash
    )
        external
        view
        returns (string memory CID, address owner, uint256 timestamp)
    {
        require(proofs[proofHash].timestamp != 0, "Proof does not exist!");

        Proof storage p = proofs[proofHash];
        return (p.CID, p.owner, p.timestamp);
    }

    // take wallet address and then addd some nonce to it to create a collision free resume id

    function getResume(
        bytes32 resumeId
    )
        external
        view
        returns (address owner, bytes32[] memory pfs, uint256 createdAt)
    {
        require(resumes[resumeId].createdAt != 0, "Resume does not exist!");

        Resume storage r = resumes[resumeId];
        return (r.owner, r.proofs, r.createdAt);
    }

    function createResume(
        bytes32 resumeId,
        bytes32 resumeHash,
        bytes32[] calldata prfshashes
    ) external {
        require(resumes[resumeId].createdAt == 0, "Resume exists");
        for (uint256 i = 0; i < prfshashes.length; i++) {
            Proof storage p = proofs[prfshashes[i]];
            require(p.timestamp != 0, "Proof missing");
            require(p.owner == msg.sender, "Not proof owner");
        }

        resumes[resumeId] = Resume({
            owner: msg.sender,
            resumeId: resumeId,
            resumeHash: resumeHash,
            createdAt: block.timestamp,
            proofs: prfshashes
        });
        // iterate in the proofs array and then add them to the current resume proofs hash
    }
}

